solution.exercise.cpp:
#include "exercise.h"
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <math.h>
bool cipher_key_valid(const char*k){if(!*k)return false;for(;*k;k++)if(*k<'a'||*k>'z')return false;return true;}static bool code(const char*k,const char*t,char*o,int sign){if(!cipher_key_valid(k))return false;size_t n=strlen(k);for(size_t i=0;t[i];i++)o[i]=(char)('a'+(t[i]-'a'+sign*(k[i%n]-'a')+26)%26);o[strlen(t)]=0;return true;}bool cipher_encode(const char*k,const char*t,char*o){return code(k,t,o,1);}bool cipher_decode(const char*k,const char*t,char*o){return code(k,t,o,-1);}void cipher_random_key(char*out,size_t n,uint64_t*s){for(size_t i=0;i<n;i++){*s=*s*6364136223846793005ULL+1;out[i]=(char)('a'+(*s>>32)%26);}out[n]=0;}

